1	package credit
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"path/filepath"
11		"unicode/utf8"
12	)
13	
14	// recordVersion 是当前记录文件格式版本。
15	const recordVersion = 1
16	
17	// fileData 是记录文件的磁盘格式。
18	type fileData struct {
19		Version       int            `json:"version"`
20		Courses       []*Course      `json:"courses"`
21		Students      []*Student     `json:"students"`
22		Requirements  []*Requirement `json:"requirements"`
23		Enrollments   []*Enrollment  `json:"enrollments"`
24		Waivers       []*Waiver      `json:"waivers"`
25		NextResultSeq int            `json:"nextResultSeq"`
26	}
27	
28	// Load 从 path 读取记录。
29	//
30	// 文件不存在时返回空记录集，existed=false，且不报错——即“从空记录开始”。
31	// 文件存在但无法读取（权限、I/O 错误等）或内容损坏（非法 JSON、结构矛盾、
32	// 引用悬空等）时返回错误，调用方绝不应把该文件当作空记录覆盖写入。
33	// 空文件同样视为损坏，而不是空记录。
34	//
35	// 整份文件必须只含一条完整记录：记录前后允许空白（空格、制表符、换行、
36	// 回车），但完整记录结束后只要还有任何内容——多出的右花括号或右方括号、
37	// 拼接的第二段 JSON、普通文字或没写完的 JSON 片段——都判为损坏并拒绝读取，
38	// 绝不依据已读到的前半条记录继续办理业务。
39	//
40	// 同一个 JSON 对象内的字段归属只能确定一次：出现两个完全同名的字段，或
41	// 两个字段名只有大小写差异却都会被读取功能识别为同一条记录字段（课程的
42	// credit 与 Credit、修读的 student 与 Student、最外层的 courses 与
43	// COURSES 等），无论两个值是否相同、顺序是否相邻，整份文件都判为损坏。
44	// 规则同时适用于最外层对象与其中的每条课程、学生、要求、修读、免修记录：
45	// 后一份即使是空数组也不能盖掉前一份。字段名以 JSON 解码后的文字比较并
46	// 按现有解码规则做大小写折叠（直接写出、Unicode 转义、大小写写法语义
47	// 等同），无法用转义加大小写的组合绕开；限制只针对同一对象，不同记录
48	// 各自携带同名字段是正常结构，字符串值里提到字段名不算重复。只出现一次
49	// 的大小写写法仍照常识别（如只有 Credit 的课程按该值读取）；不指向任何
50	// 记录字段的未知键不在此列，继续按未知字段拒绝。
51	//
52	// JSON 字符串的原始内容必须能还原为合法 Unicode 文字：字符串中直接写入的
53	// 字节不是合法 UTF-8，或 \uXXXX 转义中出现未配对的高位/低位代理项（高位
54	// 代理项后没有紧跟低位代理项、孤立的低位代理项、两个高位代理项相连等），
55	// 整份文件都判为内容损坏——标准库会把这些内容静默替换成 U+FFFD，替换后的
56	// 编号或依据绝不能当成正常内容继续查询、核对或登记，哪怕问题只在一条已拒绝
57	// 免修的依据里或本次核对不涉及的课程名称里。检查只读不写：不替用户修补转义、
58	// 不删字符、不改动任何申请状态。合法文字不受影响：中文、直接写入的补充平面
59	// 字符、完整的高低代理项转义对、转义表达的控制字符，以及用户确实写入的
60	// “�”（U+FFFD）都按原样使用。
61	//
62	// 有效免修的依据校验与首次正常申请一致：任何状态为有效（approved）的免修，
63	// 其依据必须含有实际文字；依据为空，或全部由空白字符（空格、制表符、换行、
64	// 回车、全角空格 U+3000、不换行空格 U+00A0 等，允许混用）组成时，整份记录
65	// 按内容损坏拒绝读取，即使该要求另有通过修读也不例外。已拒绝申请的依据允许
66	// 为空或只有空白。检查只读不写：不会补填依据、不会改动免修状态，也不会修剪
67	// 含实际文字的依据中原有空白。
68	//
69	// 课程开放状态字段显式写成 JSON null（"open":null，open、Open、OPEN 及解码
70	// 后等同的 Unicode 转义写法都指向同一字段，字段在课程对象中的位置不影响
71	// 结果）时，整份记录按内容损坏拒绝读取。标准库把 null 解进普通 bool 不报错，
72	// 字段保持零值 false，未定状态会被读成明确停开，进而误拒新增修读，并在后续
73	// 保存时把 null 固化成 false；因此只要课程编号、名称、学分合法而开放状态
74	// 显式为空，就拒绝整份文件——该课程尚未被要求引用、本次只查看另一名学生
75	// 也不跳过它继续办理。true（开放）与 false（停开）仍是合法状态，停开课程
76	// 照常可以建立要求、已有修读照常提交成绩；字段完全省略时沿用既有读取规则，
77	// 本次不改动。课程名称、免修依据中的普通文字“null”（字符串值）不是状态空值；
78	// 最外层 null、空数组或空列表继续按各自既有规则读取。检查只读不写：不补填
79	// 状态、不删除课程、不另存部分记录。
80	func Load(path string) (s *Store, existed bool, err error) {
81		f, err := os.Open(path)
82		if err != nil {
83			if errors.Is(err, os.ErrNotExist) {
84				return NewStore(), false, nil
85			}
86			return nil, false, fmt.Errorf("无法读取记录文件 %s：%w", path, err)
87		}
88		defer f.Close()
89	
90		fi, err := f.Stat()
91		if err != nil {
92			return nil, false, fmt.Errorf("无法读取记录文件 %s 的信息：%w", path, err)
93		}
94		if fi.Size() == 0 {
95			return nil, true, fmt.Errorf("记录文件 %s 存在但为空，内容已损坏，未做任何修改", path)
96		}
97	
98		raw, err := io.ReadAll(f)
99		if err != nil {
100			return nil, false, fmt.Errorf("无法读取记录文件 %s：%w", path, err)
101		}
102	
103		// 先按原始字节检查 JSON 字符串能否还原为合法 Unicode 文字。标准库解码
104		// 会把非法 UTF-8 字节与未配对的高/低位代理项转义静默替换成 U+FFFD，
105		// 替换后的学生编号、课程名称或免修依据绝不能当成正常内容继续办理业务
106		// （两个本来不同的编号可能被替换成同一个），这样的文件整份判为内容
107		// 损坏，哪怕问题只在一条已拒绝免修的依据里或本次核对不涉及的课程名称
108		// 里。检查只读不写：不修补转义、不删字符、不改动申请状态。
109		if err := scanStringUnicode(raw); err != nil {
110			return nil, true, fmt.Errorf(
111				"记录文件 %s 内容损坏（包含无效的 Unicode 文字：%v），未做任何修改",
112				path, err)
113		}
114	
115		// 先在 token 流上检查同一 JSON 对象内的字段归属。标准库直接解进结构
116		// 体时会用后一个重复键静默覆盖前一个，而且结构体字段按大小写不敏感
117		// 匹配 json 标签：同一门课程写了 "credit":4 与 "Credit":9（4 会被
118		// 9 悄悄顶替，两个键颠倒又变成 4），最外层同时写 courses 与 COURSES
119		// （后一份即使是空数组也会盖掉前一份），修读里的 student 与 Student
120		// 都无法明确说明字段归属。这样的记录必须整份判为损坏，绝不能据此
121		// 核对或办理——即使冲突只在本次查询没有涉及的课程或免修历史里。
122		// 仅扫描第一份完整值，其后内容仍由下方的“完整记录之后不得有多余
123		// 内容”检查处理。
124		var dupErr *duplicateFieldError
125		if err := scanDuplicateKeys(bytes.NewReader(raw)); errors.As(err, &dupErr) {
126			if dupErr.first == dupErr.second {
127				return nil, true, fmt.Errorf(
128					"记录文件 %s 内容损坏（同一 JSON 对象内字段 %q 重复出现，字段归属无法确定），未做任何修改",
129					path, dupErr.field)
130			}
131			return nil, true, fmt.Errorf(
132				"记录文件 %s 内容损坏（同一 JSON 对象内字段 %q 与 %q 仅大小写不同，读取时都指向同一记录字段 %q，字段归属无法确定），未做任何修改",
133				path, dupErr.first, dupErr.second, dupErr.field)
134		}
135	
136		// 显式的 "open":null 必须在结构体解码之前拦截。标准库把 JSON null 解进
137		// 非指针 bool 时既不报错也不改字段，零值 false 会被原样保留——于是“开放
138		// 状态未确定”的课程被读成“停开”：课程列表显示停开、新增修读被误拒，
139		// 之后任何一次需要保存的操作还会把未定状态写成明确的 false。因此只要
140		// 课程对象显式给出开放状态字段（open/Open/OPEN 及解码后等同的 Unicode
141		// 转义写法，位置不限）而值是 null，整份文件判为内容损坏，哪怕该课程
142		// 尚未被任何要求引用、本次只查看另一名学生也不跳过它继续办理。扫描只读
143		// 不写：不补填状态、不删除课程；字段省略时的既有读取规则（按零值处理）
144		// 不在此列，课程名称、免修依据中的普通文字“null”也不是状态空值。
145		var openNullErr *nullCourseOpenError
146		if err := scanNullCourseOpen(bytes.NewReader(raw)); errors.As(err, &openNullErr) {
147			return nil, true, fmt.Errorf(
148				"记录文件 %s 内容损坏（%v），未做任何修改", path, err)
149		}
150	
151		var data fileData
152		dec := json.NewDecoder(bytes.NewReader(raw))
153		dec.DisallowUnknownFields()
154		if err := dec.Decode(&data); err != nil {
155			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（JSON 解析失败：%v），未做任何修改", path, err)
156		}
157		// 完整记录之后必须只剩下空白：再解一条原始 JSON，仅 io.EOF 表示记录后
158		// 别无他物。不能用 dec.More() 判断——它只向前看“值起始”标记，记录后
159		// 多出的右花括号/右方括号会让 More() 直接返回 false 而被漏掉。再次
160		// Decode 能覆盖全部情形：成功读到值说明后面拼接了第二段 JSON；返回
161		// 语法错误或 unexpected EOF 说明尾部有孤立括号、普通文字或未写完的
162		// 片段。这些一律视为文件损坏。
163		var extra json.RawMessage
164		switch err := dec.Decode(&extra); {
165		case errors.Is(err, io.EOF):
166			// 唯一一份完整记录之后只有空白，符合格式。
167		case err == nil:
168			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（完整记录之后还拼接了其他 JSON 数据），未做任何修改", path)
169		default:
170			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（完整记录之后仍有无法解析的多余内容），未做任何修改", path)
171		}
172	
173		s = NewStore()
174		if err := s.loadData(&data); err != nil {
175			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（%v），未做任何修改", path, err)
176		}
177		return s, true, nil
178	}
