180	// loadData 校验磁盘数据并重建索引；任何矛盾都作为损坏报错。
181	func (s *Store) loadData(d *fileData) error {
182		if d.Version != recordVersion {
183			return fmt.Errorf("不支持的记录版本 %d（当前支持版本 %d）", d.Version, recordVersion)
184		}
185	
186		// 课程
187		for _, c := range d.Courses {
188			if c == nil {
189				return errors.New("存在空的课程记录")
190			}
191			if c.ID == "" {
192				return errors.New("存在没有编号的课程")
193			}
194			if c.Name == "" {
195				return fmt.Errorf("课程 %s 没有名称", c.ID)
196			}
197			if c.Credit <= 0 {
198				return fmt.Errorf("课程 %s 学分不是正整数：%d", c.ID, c.Credit)
199			}
200			if _, dup := s.courseByID[c.ID]; dup {
201				return fmt.Errorf("课程编号 %s 重复", c.ID)
202			}
203			s.courses = append(s.courses, c)
204			s.courseByID[c.ID] = c
205		}
206	
207		// 学生
208		for _, st := range d.Students {
209			if st == nil || st.ID == "" {
210				return errors.New("存在没有编号的学生记录")
211			}
212			if _, dup := s.studentByID[st.ID]; dup {
213				return fmt.Errorf("学生编号 %s 重复", st.ID)
214			}
215			s.students = append(s.students, st)
216			s.studentByID[st.ID] = st
217		}
218	
219		// 要求
220		for _, r := range d.Requirements {
221			if r == nil {
222				return errors.New("存在空的课程要求记录")
223			}
224			if r.StudentID == "" || r.ID == "" {
225				return errors.New("存在缺少学生编号或要求编号的课程要求")
226			}
227			if _, ok := s.studentByID[r.StudentID]; !ok {
228				return fmt.Errorf("要求 %s 引用了不存在的学生 %s", r.ID, r.StudentID)
229			}
230			if _, ok := s.courseByID[r.CourseID]; !ok {
231				return fmt.Errorf("学生 %s 的要求 %s 引用了不存在的课程 %s",
232					r.StudentID, r.ID, r.CourseID)
233			}
234			key := reqKey(r.StudentID, r.ID)
235			if _, dup := s.reqByKey[key]; dup {
236				return fmt.Errorf("学生 %s 的要求编号 %s 重复", r.StudentID, r.ID)
237			}
238			dk := dupKey(r.StudentID, r.CourseID)
239			if other, dup := s.reqByDup[dk]; dup {
240				return fmt.Errorf("学生 %s 就课程 %s 存在重复要求 %s 与 %s",
241					r.StudentID, r.CourseID, other, r.ID)
242			}
243			s.requirements = append(s.requirements, r)
244			s.reqByKey[key] = r
245			s.reqByDup[dk] = r.ID
246		}
247	
248		// 修读
249		usedSeq := map[int]bool{}
250		for _, e := range d.Enrollments {
251			if e == nil {
252				return errors.New("存在空的修读记录")
253			}
254			if e.StudentID == "" || e.ID == "" {
255				return errors.New("存在缺少学生编号或修读编号的修读记录")
256			}
257			if _, ok := s.studentByID[e.StudentID]; !ok {
258				return fmt.Errorf("修读 %s 引用了不存在的学生 %s", e.ID, e.StudentID)
259			}
260			r := s.reqByKey[reqKey(e.StudentID, e.ReqID)]
261			if r == nil {
262				return fmt.Errorf("学生 %s 的修读 %s 引用了不存在的要求 %s",
263					e.StudentID, e.ID, e.ReqID)
264			}
265			if e.Term == "" {
266				return fmt.Errorf("学生 %s 的修读 %s 缺少学期", e.StudentID, e.ID)
267			}
268			switch e.Result {
269			case Enrolled, Passed, Failed:
270			default:
271				return fmt.Errorf("学生 %s 的修读 %s 含非法结果 %q", e.StudentID, e.ID, e.Result)
272			}
273			if e.Result == Enrolled {
274				if e.ResultSeq != 0 {
275					return fmt.Errorf("修读 %s 尚未提交结果却带有结果序号", e.ID)
276				}
277			} else {
278				if e.ResultSeq <= 0 {
279					return fmt.Errorf("修读 %s 已提交结果但缺少结果序号", e.ID)
280				}
281				if usedSeq[e.ResultSeq] {
282					return fmt.Errorf("结果提交序号 %d 重复，记录已损坏", e.ResultSeq)
283				}
284				usedSeq[e.ResultSeq] = true
285			}
286			key := reqKey(e.StudentID, e.ID)
287			if _, dup := s.enrByKey[key]; dup {
288				return fmt.Errorf("学生 %s 的修读编号 %s 重复", e.StudentID, e.ID)
289			}
290			s.enrollments = append(s.enrollments, e)
291			s.enrByKey[key] = e
292		}
293	
294		// 免修（被拒绝的申请允许指向当时不存在的要求、依据也可以为空；
295		// 已撤销的申请则必须保留一份曾经有效的申请所必需的信息）
296		approvedReq := map[ownerKey]string{} // (student, req) -> waiverID
297		for _, w := range d.Waivers {
298			if w == nil {
299				return errors.New("存在空的免修记录")
300			}
301			if w.StudentID == "" || w.ID == "" {
302				return errors.New("存在缺少学生编号或免修编号的免修记录")
303			}
304			if _, ok := s.studentByID[w.StudentID]; !ok {
305				return fmt.Errorf("免修 %s 引用了不存在的学生 %s", w.ID, w.StudentID)
306			}
307			switch w.Status {
308			case WaiverApproved, WaiverRejected, WaiverRevoked:
309			default:
310				return fmt.Errorf("学生 %s 的免修 %s 含非法状态 %q", w.StudentID, w.ID, w.Status)
311			}
312			switch w.Status {
313			case WaiverApproved:
314				// 有效免修的依据校验与首次正常申请完全一致：依据必须含有实际
315				// 文字，空串或全部由空白字符（空格、制表符、换行、全角空格
316				// U+3000、不换行空格 U+00A0 等，含混用）组成都按内容损坏
317				// 拒绝整份记录——这样的“有效免修”无法有据可查，即使该要求
318				// 另有通过修读也不能放过。检查只读不写，绝不修剪或改写文件
319				// 中已保存的依据原文，也不把它降级成已拒绝/已撤销。
320				if blankBasis(w.Basis) {
321					return fmt.Errorf("学生 %s 的有效免修 %s 缺少依据（依据为空或全部为空白字符）",
322						w.StudentID, w.ID)
323				}
324				rk := reqKey(w.StudentID, w.ReqID)
325				if s.reqByKey[rk] == nil {
326					return fmt.Errorf("有效免修 %s 指向的要求 %s 不存在或不属于该学生", w.ID, w.ReqID)
327				}
328				if other, dup := approvedReq[rk]; dup {
329					return fmt.Errorf("学生 %s 的要求 %s 同时存在有效免修 %s 与 %s",
330						w.StudentID, w.ReqID, other, w.ID)
331				}
332				approvedReq[rk] = w.ID
333			case WaiverRevoked:
334				// 撤销只取消免修对课程要求的满足作用，不能把缺少原依据、
335				// 失去要求归属的记录变成合法历史：目标要求必须真实存在于
336				// 该免修所属学生名下（同号要求只在其他学生名下不算），
337				// 原依据必须含有非空白内容（空白口径与有效免修一致，全角
338				// 空格、不换行空格等同样不算实际依据）。检查只读不写，
339				// 依据中有实际文字时原有空白一律保留，绝不为了通过检查
340				// 改写保存下来的材料内容。失效历史不参与有效免修的唯一
341				// 性限制。
342				if s.reqByKey[reqKey(w.StudentID, w.ReqID)] == nil {
343					return fmt.Errorf("学生 %s 的已撤销免修 %s 目标要求无效（要求 %s 不存在于该学生名下）",
344						w.StudentID, w.ID, w.ReqID)
345				}
346				if blankBasis(w.Basis) {
347					return fmt.Errorf("学生 %s 的已撤销免修 %s 原依据为空", w.StudentID, w.ID)
348				}
349			}
350			key := reqKey(w.StudentID, w.ID)
351			if _, dup := s.waiverByKey[key]; dup {
352				return fmt.Errorf("学生 %s 的免修编号 %s 重复", w.StudentID, w.ID)
353			}
354			s.waivers = append(s.waivers, w)
355			s.waiverByKey[key] = w
356		}
357	
358		if d.NextResultSeq < 0 {
359			return errors.New("结果提交序号计数器为负数")
360		}
361		for seq := range usedSeq {
362			if seq > d.NextResultSeq {
363				return fmt.Errorf("结果提交序号计数器 %d 小于已有序号 %d", d.NextResultSeq, seq)
364			}
365		}
366		s.nextResultSeq = d.NextResultSeq
367		return nil
368	}
