370	// invalidTextError 表示待保存记录中含有无法原样写入文件的文字：某个字符串
371	// 字段不是合法 UTF-8。category 指出记录类别（课程、学生、课程要求、修读、
372	// 免修），id 是该条记录的编号（仅用于定位，编号本身也可能就是问题所在，
373	// 按原始字节呈现），field 指出具体字段。
374	type invalidTextError struct {
375		category string
376		id       string
377		field    string
378	}
379	
380	func (e *invalidTextError) Error() string {
381		return fmt.Sprintf(
382			"%s记录（编号 %s）的字段“%s”含无法原样保存的非法 UTF-8 文字",
383			e.category, e.id, e.field)
384	}
385	
386	// validateSaveText 检查全部待写入记录的字符串字段是否都是合法 UTF-8。
387	//
388	// 背景：encoding/json 在序列化时会把字符串里的非法 UTF-8 字节静默替换成
389	// U+FFFD（“�”）却照常返回成功。若直接保存，免修依据会被改写，两个本来
390	// 不同的学生编号还可能被替换成同一个编号，让原本可读的记录文件变成编号
391	// 重复的损坏文件，而命令却提示成功。因此凡是要写入文件的文字——课程、
392	// 学生、课程要求、修读、免修的编号、名称、学期、依据、原因等——都必须先
393	// 通过本检查，任何一个字段不合法就拒绝整次保存。
394	//
395	// 检查只读不补：绝不替换、清空或修补任何原始字符串，也不删除出问题的
396	// 那条历史（即使它只是一条已拒绝或已撤销的免修），更不会跳过该字段只存
397	// 其他记录。合法文字不受影响：中文、补充平面字符、用户确实输入的“�”
398	// （U+FFFD）都是合法 UTF-8；编号中合法的控制字符与免修依据中原有的空白
399	// 也原样保留。命令行里字面出现的“\uD800”只是反斜线加普通字母数字，是
400	// 合法 ASCII 文字，不按记录文件中的 Unicode 转义处理。
401	func (s *Store) validateSaveText() error {
402		for _, c := range s.courses {
403			if c == nil {
404				continue
405			}
406			if err := checkSaveText("课程", c.ID, "编号", c.ID); err != nil {
407				return err
408			}
409			if err := checkSaveText("课程", c.ID, "名称", c.Name); err != nil {
410				return err
411			}
412		}
413		for _, st := range s.students {
414			if st == nil {
415				continue
416			}
417			if err := checkSaveText("学生", st.ID, "编号", st.ID); err != nil {
418				return err
419			}
420		}
421		for _, r := range s.requirements {
422			if r == nil {
423				continue
424			}
425			if err := checkSaveText("课程要求", r.ID, "编号", r.ID); err != nil {
426				return err
427			}
428			if err := checkSaveText("课程要求", r.ID, "学生编号", r.StudentID); err != nil {
429				return err
430			}
431			if err := checkSaveText("课程要求", r.ID, "课程编号", r.CourseID); err != nil {
432				return err
433			}
434		}
435		for _, e := range s.enrollments {
436			if e == nil {
437				continue
438			}
439			if err := checkSaveText("修读", e.ID, "编号", e.ID); err != nil {
440				return err
441			}
442			if err := checkSaveText("修读", e.ID, "学生编号", e.StudentID); err != nil {
443				return err
444			}
445			if err := checkSaveText("修读", e.ID, "要求编号", e.ReqID); err != nil {
446				return err
447			}
448			if err := checkSaveText("修读", e.ID, "学期", e.Term); err != nil {
449				return err
450			}
451			if err := checkSaveText("修读", e.ID, "结果", string(e.Result)); err != nil {
452				return err
453			}
454		}
455		for _, w := range s.waivers {
456			if w == nil {
457				continue
458			}
459			if err := checkSaveText("免修", w.ID, "编号", w.ID); err != nil {
460				return err
461			}
462			if err := checkSaveText("免修", w.ID, "学生编号", w.StudentID); err != nil {
463				return err
464			}
465			if err := checkSaveText("免修", w.ID, "要求编号", w.ReqID); err != nil {
466				return err
467			}
468			if err := checkSaveText("免修", w.ID, "依据", w.Basis); err != nil {
469				return err
470			}
471			if err := checkSaveText("免修", w.ID, "状态", string(w.Status)); err != nil {
472				return err
473			}
474			if err := checkSaveText("免修", w.ID, "原因", w.Reason); err != nil {
475				return err
476			}
477		}
478		return nil
479	}
