489	// Save 将全部记录原子写入 path：先写同目录临时文件，再重命名覆盖，
490	// 避免写到一半时损坏原文件。
491	//
492	// 写入前先校验全部待保存字符串都是合法 UTF-8：标准库序列化会把非法字节
493	// 静默替换成 U+FFFD，因此含非法文字的数据绝不能进入序列化与临时文件阶段。
494	// 校验失败时整次保存直接返回错误——不创建/不改动目标文件（目标原本不
495	// 存在时也不会留下新记录文件或临时文件），不替换、清空或修补待保存记录
496	// 中的任何原始字符串，即使问题只出现在一条已拒绝或已撤销免修的字段里。
497	func (s *Store) Save(path string) (err error) {
498		if err := s.validateSaveText(); err != nil {
499			return fmt.Errorf("记录中存在无法原样保存的文字，拒绝写入 %s：%w", path, err)
500		}
501		data := fileData{
502			Version:       recordVersion,
503			Courses:       s.courses,
504			Students:      s.students,
505			Requirements:  s.requirements,
506			Enrollments:   s.enrollments,
507			Waivers:       s.waivers,
508			NextResultSeq: s.nextResultSeq,
509		}
510		buf, err := json.MarshalIndent(&data, "", "  ")
511		if err != nil {
512			return fmt.Errorf("无法序列化记录：%w", err)
513		}
514		buf = append(buf, '\n')
515	
516		dir := filepath.Dir(path)
517		if dir == "" {
518			dir = "."
519		}
520		tmp, err := os.CreateTemp(dir, ".credit-*.tmp")
521		if err != nil {
522			return fmt.Errorf("无法在 %s 创建临时记录文件：%w", dir, err)
523		}
524		tmpName := tmp.Name()
525		defer func() {
526			if err != nil {
527				tmp.Close()
528				os.Remove(tmpName)
529			}
530		}()
531		if _, err = tmp.Write(buf); err != nil {
532			return fmt.Errorf("写入记录文件失败：%w", err)
533		}
534		if err = tmp.Sync(); err != nil {
535			return fmt.Errorf("写入记录文件失败：%w", err)
536		}
537		if err = tmp.Close(); err != nil {
538			return fmt.Errorf("写入记录文件失败：%w", err)
539		}
540		if err = os.Chmod(tmpName, 0o600); err != nil {
541			return fmt.Errorf("设置记录文件权限失败：%w", err)
542		}
543		if err = os.Rename(tmpName, path); err != nil {
544			return fmt.Errorf("保存记录文件 %s 失败：%w", path, err)
545		}
546		return nil
547	}
