	}
	if !existed {
		t.Fatalf("应标记文件已存在，existed=%v err=%v", existed, err)
	}
	if msg := err.Error(); !strings.Contains(msg, "内容损坏") ||
		!strings.Contains(msg, "s1") || !strings.Contains(msg, "w1") {
